function citationAuthor(r){let name=r.author||'';if(name.includes(' / '))name=name.split(' / ')[0];if(/^[A-Za-zÀ-ž]+(?: [A-Za-zÀ-ž.]+)+$/.test(name)){const parts=name.split(' ');name=parts.pop()+', '+parts.join(' ')}return name}
