function bookTextLabel(){return ({zh:'书内篇目',en:'Texts within books',fr:'Textes contenus dans les livres'})[document.documentElement.lang.slice(0,2)]||'书内篇目'}
function citationCategoryLabel(category){return category===8?bookTextLabel():libraryLabels()[category]}
function containedCitation(t){const e=suppliedEditions.find(e=>e.id===t.editionId);if(!e)return null;const record=editionCitationRecord(e);return {...record,id:'text-'+t.id,editionId:t.editionId,author:t.author,role:'',title:t.title,container:e.title,editors:(e.editors||[]).filter(x=>['编','编选'].includes(x.role)).map(x=>x.name).join('、'),pages:t.startPage!==null&&t.endPage!==null?(t.startPage===t.endPage?String(t.startPage):t.startPage+'–'+t.endPage):'',kind:'chapter',category:8,incomplete:!t.author||!record.year||t.endPage===null}}
